<script setup lang="ts">import{Head,Link}from'@inertiajs/vue3';import AdvertiserPortalHeader from '@/components/Advertiser/AdvertiserPortalHeader.vue';import{Button}from'@/components/ui/button';defineProps<{advertiser:any;membership:any;campaign:any}>();const money=(v:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((v||0)/100);</script><template><Head :title="campaign.name"/><div class="space-y-6 p-6"><AdvertiserPortalHeader :title="campaign.name" :description="`${campaign.status} · ${campaign.objective||'Advertising campaign'}`" :advertiser="advertiser"><template #actions><Button as-child><Link :href="`/advertiser/campaigns/${campaign.id}/creatives`">View creatives</Link></Button></template></AdvertiserPortalHeader><div class="grid gap-4 md:grid-cols-4"><div class="rounded-xl border p-4"><p class="text-sm text-muted-foreground">Budget</p><p class="text-xl font-semibold">{{money(campaign.budget_cents)}}</p></div><div class="rounded-xl border p-4"><p class="text-sm text-muted-foreground">Impression goal</p><p class="text-xl font-semibold">{{campaign.impression_goal||'—'}}</p></div><div class="rounded-xl border p-4"><p class="text-sm text-muted-foreground">Click goal</p><p class="text-xl font-semibold">{{campaign.click_goal||'—'}}</p></div><div class="rounded-xl border p-4"><p class="text-sm text-muted-foreground">Creatives</p><p class="text-xl font-semibold">{{campaign.creatives.length}}</p></div></div><section class="rounded-xl border p-5"><h2 class="font-semibold">Placements</h2><div class="mt-4 grid gap-3 md:grid-cols-2"><div v-for="p in campaign.placements" class="rounded-lg border p-3"><p class="font-medium">{{p.name}}</p><p class="text-sm text-muted-foreground">{{p.width||'Flexible'}} × {{p.height||'Flexible'}}</p></div></div></section></div></template>
